// Home Briefing read inside Ask (register P1 "Home Briefing / Home Gazette"; FRD v1.327). Reads getHomeBriefingView, the same call the page's route
// makes, with `readOnly` so that looking never creates the household member's preference row (the route's GET does). The briefing is the caller's own:
// their preferences, their deliveries and their reading of each item. Nothing is generated by reading.
import { type AskPresentationBlock } from '../../../productFramework/ask/ask.contract';
import { type AskOperationResult } from '../askOperationRegistry';
import { registerCapabilityHandler } from '../capabilityHandlerRegistry';
import { getHomeBriefingView } from '../../../homeBriefing/homeBriefing.service';
import { ensurePropertyAccess } from '../askHandlerSupport';
import { humanDate } from '../askFormatting';
import {
  BRIEFING_CADENCE_LABELS, BRIEFING_CHANNEL_LABELS, BRIEFING_COMMAND_ACTION_IDS, BRIEFING_COMMAND_MESSAGES, BRIEFING_ITEM_ENTITY_TYPE, BRIEFING_PROPERTY_ENTITY_TYPE,
  BRIEFING_TOPIC_LABELS,
} from '../support/homeBriefingCommand';

type BriefingView = Awaited<ReturnType<typeof getHomeBriefingView>>;
const MATERIALITY_LABELS: Record<string, string> = { HIGH: 'Important', MEDIUM: 'Worth a look', LOW: 'For your information' };

export function homeBriefingFromView(view: BriefingView, propertyId: string, canChange = false): AskOperationResult {
  const { preference, current } = view;
  const items = current?.items ?? [];
  const unread = view.unreadMaterialCount;
  const channels = (preference.channels as string[]).map((c) => BRIEFING_CHANNEL_LABELS[c] ?? c).join(', ');
  const topics = (preference.topics as string[]).length ? (preference.topics as string[]).map((t) => BRIEFING_TOPIC_LABELS[t] ?? t).join(', ') : 'All topics';
  const action = (kind: 'GENERATE' | 'PREFERENCES', label: string, style: 'PRIMARY' | 'SECONDARY') => ({
    id: BRIEFING_COMMAND_ACTION_IDS[kind], label, interactionType: 'START_WORKFLOW' as const, message: BRIEFING_COMMAND_MESSAGES[kind],
    operationId: 'HOME_BRIEFING_COMMAND' as const, entityType: BRIEFING_PROPERTY_ENTITY_TYPE, entityId: propertyId, style,
  });
  const blocks: AskPresentationBlock[] = [{
    type: 'SUMMARY', id: 'home-briefing-summary',
    title: !preference.enabled ? 'Your home briefing is turned off'
      : current ? `${items.length} update${items.length === 1 ? '' : 's'} in your latest briefing${unread ? `, ${unread} not yet seen` : ''}` : 'No briefing has been prepared yet',
    body: `${preference.enabled ? `${BRIEFING_CADENCE_LABELS[String(preference.cadence)] ?? preference.cadence} · ${channels} · ${topics}.` : 'Turn it on to have changes to your home summarised for you.'}${current ? ` Prepared ${humanDate(new Date(current.generatedAt)) ?? 'recently'}.` : ''} ${view.editorialBoundary}`,
    tone: unread ? 'CAUTION' : 'DEFAULT',
    actions: canChange ? [
      ...(preference.enabled ? [action('GENERATE', current ? 'Prepare a fresh briefing' : 'Prepare my briefing', 'PRIMARY')] : []),
      action('PREFERENCES', 'Change settings', 'SECONDARY'),
    ] : [],
  }];
  if (items.length) {
    const open = (item: (typeof items)[number]) => !item.seenAt && !item.actedAt && !item.dismissedAt && !item.notUsefulAt;
    const itemActions = (item: (typeof items)[number]) => (canChange && open(item) ? ([
      ['SEEN', 'Mark seen', 'SECONDARY'], ['DISMISS', 'Dismiss', 'QUIET'], ['NOT_USEFUL', 'Not useful', 'QUIET'],
    ] as const).map(([kind, label, style]) => ({
      id: BRIEFING_COMMAND_ACTION_IDS[kind], label, message: BRIEFING_COMMAND_MESSAGES[kind], operationId: 'HOME_BRIEFING_COMMAND' as const, interactionType: 'MUTATE_RECORD' as const, style,
    })) : []);
    blocks.push({
      type: 'GROUPED_LIST', filters: [], id: 'home-briefing-items', title: 'In your latest briefing',
      description: 'Most important first. Each comes from your verified home records and reviewed sources.',
      sections: [{
        id: 'briefing-current', title: 'Updates', count: items.length,
        items: items.slice(0, 20).map((item) => ({
          id: item.id, title: item.title, description: item.summary.slice(0, 300),
          meta: [
            BRIEFING_TOPIC_LABELS[item.topic] ?? item.topic, MATERIALITY_LABELS[String(item.materiality)] ?? String(item.materiality),
            item.actedAt ? 'Acted on' : item.dismissedAt ? 'Dismissed' : item.notUsefulAt ? 'Marked not useful' : item.seenAt ? 'Seen' : null,
          ].filter((value): value is string => Boolean(value)),
          status: item.actedAt ? 'ACTED' : item.dismissedAt ? 'DISMISSED' : item.notUsefulAt ? 'NOT_USEFUL' : item.seenAt ? 'SEEN' : 'NEW',
          href: null, entityType: BRIEFING_ITEM_ENTITY_TYPE, actions: itemActions(item),
        })),
      }],
      actions: [],
    });
  }
  if (view.archive.length) {
    blocks.push({
      type: 'LIMITATION', id: 'home-briefing-archive', title: `${view.archive.length} earlier briefing${view.archive.length === 1 ? '' : 's'}`,
      body: view.archiveBoundary, severity: 'INFO',
    });
  }
  return {
    status: 'ANSWERED', reasonCode: !preference.enabled ? 'HOME_BRIEFING_DISABLED' : current ? (unread ? 'HOME_BRIEFING_UNREAD' : 'HOME_BRIEFING_CURRENT') : 'HOME_BRIEFING_NONE_YET',
    blocks, suggestions: [],
  };
}

registerCapabilityHandler('home-briefing.view', async (envelope, deps) => {
  await (deps.propertyAccess ?? ensurePropertyAccess(envelope.userId, envelope.propertyId!));
  const view = await getHomeBriefingView(envelope.propertyId!, envelope.userId, { readOnly: true });
  // CALLER_SCOPED: the briefing is the caller's own, so every member who can see it may change theirs.
  return homeBriefingFromView(view, envelope.propertyId!, true);
});
